import yaml
import json

with open('/home/ubuntu/.agent-ml-research-idea_gen_0509_17/projects/recovery_aware_struct_prune/registry.yaml', 'r') as f:
    registry = yaml.safe_load(f)

# Extract all MATH-500 evals with DONE status and metrics
results = {}
for exp_id, exp_data in registry.get('experiments', {}).items():
    if 'math500' in exp_id.lower():
        status = exp_data.get('status', 'UNKNOWN')
        conclusion = exp_data.get('conclusion', 'UNKNOWN')
        metrics = exp_data.get('metrics', {})

        # Look for accuracy metrics
        accuracy = None
        if 'math500_acc' in metrics:
            accuracy = metrics['math500_acc']
        elif 'accuracy' in metrics:
            accuracy = metrics['accuracy']

        # Only include if DONE and has accuracy
        if status == 'DONE' and accuracy is not None:
            results[exp_id] = {
                'status': status,
                'conclusion': conclusion,
                'accuracy': accuracy
            }

# Sort by method name and print
for exp_id in sorted(results.keys()):
    data = results[exp_id]
    print(f"{exp_id}: {data['accuracy']:.3f} (conclusion: {data['conclusion']})")
EOF

